-- HR platform MVP schema (PostgreSQL 13+)
-- Run on a dedicated database/schema. UUIDs are generated by pgcrypto.
CREATE EXTENSION IF NOT EXISTS pgcrypto;

BEGIN;

-- 1. Vacancies
CREATE TABLE vacancies (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    title VARCHAR(255) NOT NULL,
    status VARCHAR(20) NOT NULL DEFAULT 'active'
        CHECK (status IN ('draft', 'active', 'closed')),
    source_json JSONB NOT NULL DEFAULT '{}'::jsonb,
    criteria_version INTEGER NOT NULL DEFAULT 1
        CHECK (criteria_version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 2. Vacancy requirements
CREATE TABLE vacancy_criteria (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    vacancy_id UUID NOT NULL REFERENCES vacancies(id) ON DELETE CASCADE,
    name VARCHAR(255) NOT NULL,
    importance VARCHAR(20) NOT NULL DEFAULT 'preferred'
        CHECK (importance IN ('required', 'preferred', 'irrelevant')),
    description TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 3. Candidate applications
CREATE TABLE responses (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    vacancy_id UUID NOT NULL REFERENCES vacancies(id) ON DELETE CASCADE,
    candidate_name VARCHAR(255),
    source_json JSONB NOT NULL,
    workflow_status VARCHAR(20) NOT NULL DEFAULT 'new'
        CHECK (workflow_status IN ('new', 'reviewed', 'contacted')),
    is_archived BOOLEAN NOT NULL DEFAULT FALSE,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 4. Background processing tasks
CREATE TABLE analysis_tasks (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    vacancy_id UUID REFERENCES vacancies(id) ON DELETE CASCADE,
    response_id UUID REFERENCES responses(id) ON DELETE CASCADE,
    task_type VARCHAR(30) NOT NULL
        CHECK (task_type IN ('matching', 'questions')),
    status VARCHAR(20) NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'processing', 'completed', 'failed')),
    error_message TEXT,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    completed_at TIMESTAMPTZ,
    CONSTRAINT analysis_tasks_target_required
        CHECK (vacancy_id IS NOT NULL OR response_id IS NOT NULL)
);

-- 5. Current matching result per application
CREATE TABLE match_results (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    response_id UUID NOT NULL UNIQUE REFERENCES responses(id) ON DELETE CASCADE,
    match_score NUMERIC(5,2) CHECK (match_score BETWEEN 0 AND 100),
    match_status VARCHAR(10) NOT NULL
        CHECK (match_status IN ('green', 'yellow', 'red')),
    missing_data JSONB NOT NULL DEFAULT '[]'::jsonb,
    criteria_version INTEGER NOT NULL CHECK (criteria_version > 0),
    analyzed_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 6. Requirement-by-requirement evaluation
CREATE TABLE criterion_evaluations (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    match_result_id UUID NOT NULL REFERENCES match_results(id) ON DELETE CASCADE,
    criterion_id UUID NOT NULL REFERENCES vacancy_criteria(id) ON DELETE CASCADE,
    status VARCHAR(20) NOT NULL
        CHECK (status IN ('matched', 'partial', 'not_matched', 'unknown')),
    explanation TEXT,
    evidence JSONB NOT NULL DEFAULT '[]'::jsonb,
    UNIQUE (match_result_id, criterion_id)
);

-- 7. Structured candidate reports
CREATE TABLE reports (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    response_id UUID NOT NULL UNIQUE REFERENCES responses(id) ON DELETE CASCADE,
    summary TEXT,
    strengths JSONB NOT NULL DEFAULT '[]'::jsonb,
    structured_resume JSONB NOT NULL DEFAULT '{}'::jsonb,
    criteria_version INTEGER NOT NULL CHECK (criteria_version > 0),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

-- 8. Generated interview questions
CREATE TABLE questions (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    report_id UUID NOT NULL REFERENCES reports(id) ON DELETE CASCADE,
    criterion_id UUID REFERENCES vacancy_criteria(id) ON DELETE SET NULL,
    question TEXT NOT NULL,
    expected_answer TEXT,
    follow_up_hint TEXT,
    position INTEGER NOT NULL DEFAULT 0
);

-- Indexes for typical API access patterns
CREATE INDEX idx_criteria_vacancy ON vacancy_criteria(vacancy_id);
CREATE INDEX idx_responses_vacancy ON responses(vacancy_id);
CREATE INDEX idx_responses_status ON responses(vacancy_id, workflow_status, is_archived);
CREATE INDEX idx_match_results_score ON match_results(match_score DESC);
CREATE INDEX idx_tasks_status ON analysis_tasks(status);
CREATE INDEX idx_evaluations_match ON criterion_evaluations(match_result_id);
CREATE INDEX idx_questions_report ON questions(report_id, position);

COMMIT;
